// puny-ref.mjs — from-scratch RFC 3492 bootstring (Punycode) that reproduces
// CPython's `encodings/punycode.py` codec bit-for-bit, including its quirks.
// Pure ESM, zero dependencies. Node's built-in `punycode` module and the WHATWG
// URL class are deliberately NOT used.
//
// Bootstring parameters (RFC 3492 section 5):
//   base = 36, tmin = 1, tmax = 26, skew = 38, damp = 700,
//   initial_bias = 72, initial_n = 128 (0x80), delimiter = '-'
//   digit alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 0x80;
const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';

export class PunycodeError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'PunycodeError';
    this.code = code; // 'incomplete' | 'invalid-digit' | 'invalid-char'
  }
}

/* ------------------------------------------------------------------ shared */

// CPython: def T(j, bias)
function T(j, bias) {
  const res = BASE * (j + 1) - bias;
  if (res < TMIN) return TMIN;
  if (res > TMAX) return TMAX;
  return res;
}

// CPython: def adapt(delta, first, numchars)  (RFC 3492 adapt, inlined consts)
function adapt(delta, first, numchars) {
  delta = first ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  delta += Math.floor(delta / numchars);
  let divisions = 0;
  // ((base - tmin) * tmax) // 2 == 455
  while (delta > 455) {
    delta = Math.floor(delta / (BASE - TMIN)); // 35
    divisions += BASE;
  }
  return divisions + Math.floor((BASE * delta) / (delta + SKEW));
}

/** Iterate a JS string as an array of code points (lone surrogates preserved). */
export function toCodePoints(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        out.push((c - 0xd800) * 0x400 + (d - 0xdc00) + 0x10000);
        i++;
        continue;
      }
    }
    out.push(c);
  }
  return out;
}

/** Inverse of toCodePoints; keeps lone surrogates as-is. */
export function fromCodePoints(cps) {
  let s = '';
  for (const cp of cps) {
    if (cp <= 0xffff) s += String.fromCharCode(cp);
    else {
      const v = cp - 0x10000;
      s += String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
    }
  }
  return s;
}

/* ----------------------------------------------------------------- encoder */

// CPython: def segregate(str) -> (basic bytes, sorted set of non-ASCII chars)
function segregate(cps) {
  const base = [];
  const ext = new Set();
  for (const cp of cps) {
    if (cp < 128) base.push(cp);
    else ext.add(cp);
  }
  return { base, extended: [...ext].sort((a, b) => a - b) };
}

// CPython: def selective_len(str, max)
function selectiveLen(cps, max) {
  let res = 0;
  for (const cp of cps) if (cp < max) res++;
  return res;
}

// CPython: def selective_find(str, char, index, pos)
function selectiveFind(cps, char, index, pos) {
  const l = cps.length;
  for (;;) {
    pos += 1;
    if (pos === l) return [-1, -1];
    const c = cps[pos];
    if (c === char) return [index + 1, pos];
    else if (c < char) index += 1;
  }
}

// CPython: def insertion_unsort(str, extended)
function insertionUnsort(cps, extended) {
  let oldchar = 0x80;
  const result = [];
  let oldindex = -1;
  for (const char of extended) {
    let index = -1;
    let pos = -1;
    const curlen = selectiveLen(cps, char);
    let delta = (curlen + 1) * (char - oldchar);
    for (;;) {
      [index, pos] = selectiveFind(cps, char, index, pos);
      if (index === -1) break;
      delta += index - oldindex;
      result.push(delta - 1);
      oldindex = index;
      delta = 0;
    }
    oldchar = char;
  }
  return result;
}

// CPython: def generate_generalized_integer(N, bias)
function generateGeneralizedInteger(N, bias) {
  let out = '';
  let j = 0;
  for (;;) {
    const t = T(j, bias);
    if (N < t) {
      out += DIGITS[N];
      return out;
    }
    out += DIGITS[t + ((N - t) % (BASE - t))];
    N = Math.floor((N - t) / (BASE - t));
    j += 1;
  }
}

// CPython: def generate_integers(baselen, deltas)
function generateIntegers(baselen, deltas) {
  let out = '';
  let bias = INITIAL_BIAS;
  for (let points = 0; points < deltas.length; points++) {
    const delta = deltas[points];
    out += generateGeneralizedInteger(delta, bias);
    bias = adapt(delta, points === 0, baselen + points + 1);
  }
  return out;
}

/**
 * CPython: def punycode_encode(text) -> bytes
 * Returns the ASCII punycode body (WITHOUT the "xn--" prefix).
 * QUIRK: when the basic string is empty, NO '-' delimiter is emitted.
 */
export function punycodeEncode(text) {
  const cps = Array.isArray(text) ? text : toCodePoints(text);
  const { base, extended } = segregate(cps);
  const ext = generateIntegers(base.length, insertionUnsort(cps, extended));
  const baseStr = base.map(c => String.fromCharCode(c)).join('');
  if (base.length) return baseStr + '-' + ext;
  return ext;
}

/* ----------------------------------------------------------------- decoder */

// CPython: def decode_generalized_number(extended, extpos, bias, errors='strict')
function decodeGeneralizedNumber(extended, extpos, bias) {
  let result = 0;
  let w = 1;
  let j = 0;
  for (;;) {
    if (extpos >= extended.length) {
      throw new PunycodeError('incomplete', 'incomplete punicode string');
    }
    const char = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (char >= 0x41 && char <= 0x5a) digit = char - 0x41; // A-Z -> 0..25
    else if (char >= 0x30 && char <= 0x39) digit = char - 22; // 0-9 -> 26..35
    else {
      throw new PunycodeError(
        'invalid-digit',
        `Invalid extended code point '${extended[extpos - 1]}'`
      );
    }
    const t = T(j, bias);
    result += digit * w;
    if (digit < t) return [extpos, result];
    w = w * (BASE - t);
    j += 1;
  }
}

// CPython: def insertion_sort(base, extended, errors='strict')
function insertionSort(baseCps, extended) {
  let base = baseCps.slice();
  let char = INITIAL_N;
  let pos = -1;
  let bias = INITIAL_BIAS;
  let extpos = 0;
  while (extpos < extended.length) {
    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
    pos += delta + 1;
    char += Math.floor(pos / (base.length + 1));
    if (char > 0x10ffff) {
      throw new PunycodeError('invalid-char', `Invalid character U+${char.toString(16)}`);
    }
    pos = pos % (base.length + 1);
    base = base.slice(0, pos).concat([char], base.slice(pos));
    bias = adapt(delta, extpos === 0, base.length);
    extpos = newpos;
  }
  return base;
}

/**
 * CPython: bytes.decode('punycode')  (errors='strict')
 * `text` is the ASCII punycode body WITHOUT the "xn--" prefix.
 * Returns a JS string (may contain lone surrogates — see QUIRKS).
 * Throws PunycodeError (== Python UnicodeError) on failure.
 */
export function punycodeDecode(text) {
  const pos = text.lastIndexOf('-');
  let baseCps, extended;
  if (pos === -1) {
    baseCps = [];
    extended = text.toUpperCase();
  } else {
    baseCps = toCodePoints(text.slice(0, pos));
    extended = text.slice(pos + 1).toUpperCase();
  }
  return fromCodePoints(insertionSort(baseCps, extended));
}

/* ------------------------------------------------------------- convenience */

/** idna.alabel() body for a non-ASCII label. */
export function toASCII(label) {
  return 'xn--' + punycodeEncode(label);
}

/** idna.ulabel() punycode step for an "xn--"-prefixed (already lowercased) label. */
export function fromASCII(alabel) {
  const low = alabel.toLowerCase();
  if (!low.startsWith('xn--')) throw new PunycodeError('no-prefix', 'not an A-label');
  const body = low.slice(4);
  if (!body) throw new PunycodeError('empty', 'Malformed A-label, no Punycode eligible content found');
  if (body.endsWith('-')) throw new PunycodeError('trailing-hyphen', 'A-label must not end with a hyphen');
  return punycodeDecode(body);
}

export default { punycodeEncode, punycodeDecode, toASCII, fromASCII, PunycodeError };
